import { useState } from 'react';
import { JxButton, JxCalendar } from '@jinx-ui/react';

type ReportDatePickerProps = {
  defaultValue?: Date;
  onChange?: (date: Date | null) => void;
};

const PRESETS = [
  { label: 'Сегодня', daysAgo: 0 },
  { label: 'Вчера', daysAgo: 1 },
  { label: 'Неделя назад', daysAgo: 7 },
] as const;

function atStartOfDay(date: Date): Date {
  const copy = new Date(date);
  copy.setHours(0, 0, 0, 0);
  return copy;
}

function shiftDays(daysAgo: number): Date {
  const date = atStartOfDay(new Date());
  date.setDate(date.getDate() - daysAgo);
  return date;
}

function isSameDay(a: Date | null, b: Date): boolean {
  return a !== null && atStartOfDay(a).getTime() === b.getTime();
}

export default function ReportDatePicker({ defaultValue, onChange }: ReportDatePickerProps) {
  const [date, setDate] = useState<Date | null>(defaultValue ?? null);

  const select = (next: Date | null) => {
    const normalized = next ? atStartOfDay(next) : null;
    setDate(normalized);
    onChange?.(normalized);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-3)',
      }}
    >
      <div
        role="group"
        aria-label="Быстрый выбор даты отчёта"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2)' }}
      >
        {PRESETS.map((preset) => {
          const presetDate = shiftDays(preset.daysAgo);
          const active = isSameDay(date, presetDate);
          return (
            <JxButton
              key={preset.label}
              type="button"
              size="sm"
              variant={active ? 'primary' : 'ghost'}
              aria-pressed={active}
              onClick={() => select(presetDate)}
            >
              {preset.label}
            </JxButton>
          );
        })}
      </div>

      <JxCalendar
        aria-label="Дата отчёта"
        value={date}
        onValueChange={(next: Date | null) => select(next)}
      />
    </div>
  );
}

